from modele import *

chapitre(1,'fractions','Nombres rationnels et fractions','1 · Nombres et calculs',
'Vocabulaire · Priorités · Fractions irréductibles · Problèmes',
['Calculer en respectant les priorités et les signes.','Rendre une fraction irréductible et calculer exactement.','Résoudre un problème faisant appel à des fractions.'],
['Tables de multiplication, nombres relatifs et opérations sur les fractions.'],[
r'''\essSection{1}{Vocabulaire et priorités}
\begin{definition}Un quotient est le résultat d’une division, ou l’écriture de cette division. Une fraction est le quotient $a/b$ de deux entiers, avec $b\ne0$ : elle désigne à la fois un nombre et une écriture. Un nombre rationnel est un nombre égal au quotient de deux entiers.\end{definition}
\begin{propriete}Les parenthèses sont prioritaires, puis les puissances, les produits et quotients, enfin les sommes et différences. À priorité égale, on calcule de gauche à droite.\end{propriete}
\begin{exemple}$-4+3\times(5-7)=-4+3\times(-2)=-10$. Pour $(-3)^2$, le carré porte sur le nombre $-3$ ; dans $-3^2$, le signe moins est extérieur au carré.\end{exemple}
\begin{savoirfaire}[Gérer les signes]Un produit ou un quotient de deux nombres de même signe est positif ; de signes contraires, il est négatif. Pour une somme, ces règles ne s’appliquent pas : comparer les valeurs et les signes.\end{savoirfaire}
\begin{definition}[Ensembles de nombres]$\mathbb N$ désigne les entiers naturels, $\mathbb Z$ les entiers relatifs, $\mathbb D$ les nombres décimaux et $\mathbb Q$ les nombres rationnels. Chacun est contenu dans le suivant. Ainsi $-3\in\mathbb Z$, $2{,}5\in\mathbb D$ et $1/3\in\mathbb Q$, mais $1/3$ n’est pas décimal.\end{definition}
\begin{attention}On ne divise jamais par zéro. Une égalité doit relier des nombres égaux : ne pas enchaîner un résultat partiel avec tout le calcul initial.\end{attention}''',
r'''\essSection{2}{Calculer avec des fractions}
\begin{propriete}Pour additionner, utiliser un dénominateur commun. Pour multiplier, multiplier les numérateurs et les dénominateurs. Pour diviser par une fraction non nulle, multiplier par son inverse.\end{propriete}
\begin{exemple}
\[\frac34-\frac56=\frac9{12}-\frac{10}{12}=-\frac1{12},
\qquad \frac23\div\frac57=\frac23\times\frac75=\frac{14}{15}.\]
\end{exemple}
\begin{definition}Une fraction est irréductible lorsque son numérateur et son dénominateur n’ont pas d’autre diviseur commun positif que 1.\end{definition}
\begin{savoirfaire}[Rendre irréductible]Simplifier successivement par des diviseurs communs, en s’aidant des critères de divisibilité, ou décomposer les deux termes en facteurs premiers. $\dfrac{84}{126}=\dfrac{42}{63}=\dfrac{14}{21}=\dfrac23$ : on a simplifié par 2, par 3, puis par 7.\end{savoirfaire}
\begin{savoirfaire}[Une fraction d’une quantité]Prendre $3/5$ de 40 revient à calculer $40\times3/5=24$. « Les $2/3$ du reste » impose de calculer d’abord le reste : le tout de référence a changé. Un schéma en barres aide à suivre ces parts.\end{savoirfaire}
\begin{attention}On simplifie des facteurs dans un produit, jamais des termes isolés d’une somme. Ainsi $(6+3)/3=3$, et non $6+1$.\end{attention}'''],[
E('Une température',r"Le matin, il fait $-6\,^\circ$C. La température augmente de 11 degrés puis baisse de 4 degrés. Quelle est la température finale ?",
r"On respecte l’ordre des changements : $-6+11=5$, puis $5-4=\res{1\,^\circ\mathrm C}$. Une augmentation se traduit par une addition, même si la température initiale est négative.",
'Traduire chaque changement avec son signe.','assert -6+11-4==1'),
E('Respecter les priorités',r"Calculer $A=18-3(2+5)$ et $B=(18-3)(2+5)$.",
r"Dans $A$, la parenthèse vaut 7, puis $3\times7=21$ : $\res{A=-3}$. Dans $B$, les deux parenthèses donnent 15 et 7 : $\res{B=105}$. Les parenthèses ont changé les facteurs du produit.",
'Calculer les parenthèses avant les produits.','assert 18-3*(2+5)==-3 and (18-3)*(2+5)==105'),
E('Deux écritures, un nombre',r"Compléter $\dfrac5{8}=\dfrac{\,?\,}{40}$ et $\dfrac{42}{63}=\dfrac2{\,?\,}$.",
r"On multiplie 8 par 5, donc aussi 5 par 5 : $\res{25/40}$. On divise 42 par 21, donc aussi 63 par 21 : $\res{2/3}$. La même opération sur les deux termes conserve le quotient.",
'Appliquer le même facteur aux deux termes.','assert Rational(25,40)==Rational(5,8) and Rational(42,63)==Rational(2,3)'),
E('Une somme exacte',r"Calculer $\dfrac7{12}+\dfrac5{18}$ et donner une fraction irréductible.",
r"Un dénominateur commun est 36 : $7/12=21/36$ et $5/18=10/36$. La somme est $\res{31/36}$. Le numérateur 31 est premier et ne divise pas 36 : la fraction est irréductible.",
'Choisir un dénominateur commun adapté.','assert Rational(7,12)+Rational(5,18)==Rational(31,36) and gcd(31,36)==1'),
E('Produit et quotient',r"Calculer $\dfrac{-9}{14}\times\dfrac7{15}$ puis $\dfrac35\div\dfrac{-9}{10}$.",
r"Dans le produit, on simplifie 7 avec 14 et 9 avec 15 : $\res{-3/10}$. Dans le quotient, on multiplie par l’inverse : $(3/5)\times(-10/9)=\res{-2/3}$. Les deux résultats sont négatifs.",
'Simplifier les facteurs et inverser le diviseur.','assert Rational(-9,14)*Rational(7,15)==Rational(-3,10) and Rational(3,5)/Rational(-9,10)==Rational(-2,3)'),
E('Simplifications successives',r"Rendre irréductibles $\dfrac{150}{225}$ et $\dfrac{126}{198}$ par simplifications successives. Les deux fractions sont-elles égales ?",
r"$150/225=30/45=6/9=\res{2/3}$, en simplifiant par 5, par 5, puis par 3. $126/198=63/99=7/11$, en simplifiant par 2 puis par 9 : $\res{7/11}$. Comme $2\times11=22$ et $7\times3=21$, les fractions $\res{\text{ne sont pas égales}}$.",
'Chercher un diviseur commun visible, puis recommencer.','assert Rational(150,225)==Rational(2,3) and Rational(126,198)==Rational(7,11) and Rational(2,3)!=Rational(7,11)'),
E('Comparer sans arrondir',r"Ranger $-\dfrac34$, $-\dfrac56$ et $-\dfrac7{12}$ dans l’ordre croissant.",
r"Avec le dénominateur 12, les numérateurs sont $-9,-10,-7$. Ainsi $\res{-5/6<-3/4<-7/12}$. Parmi des négatifs, le nombre le plus éloigné de zéro est le plus petit.",
'Ramener les fractions à un dénominateur positif commun.','assert Rational(-5,6)<Rational(-3,4)<Rational(-7,12)'),
E('Une expression à étages',r"Calculer exactement $C=\dfrac{\frac23+\frac16}{\frac54-\frac12}$.",
r"Le numérateur vaut $4/6+1/6=5/6$ ; le dénominateur vaut $5/4-2/4=3/4$, non nul. Donc $C=(5/6)\times(4/3)=\res{10/9}$.",
'Séparer le numérateur et le dénominateur avant de diviser.','assert (Rational(2,3)+Rational(1,6))/(Rational(5,4)-Rational(1,2))==Rational(10,9)'),
E('Des ensembles de nombres',r"Pour chacun des nombres $-7$ ; $0$ ; $2{,}5$ ; $\dfrac{12}{4}$ ; $-\dfrac53$, donner le plus petit des ensembles $\mathbb N$, $\mathbb Z$, $\mathbb D$, $\mathbb Q$ qui le contient.",
r"$-7\in\res{\mathbb Z}$ ; $0\in\res{\mathbb N}$ ; $2{,}5=25/10\in\res{\mathbb D}$ ; $12/4=3\in\res{\mathbb N}$ ; $-5/3\in\res{\mathbb Q}$. Ce dernier n’est pas décimal : si $5/3$ s’écrivait $a/10^k$, on aurait $3a=5\times10^k$, impossible car 3 ne divise pas $5\times10^k$.",
'Simplifier l’écriture avant de choisir l’ensemble.','assert Rational(12,4)==3 and Rational(-5,3).q==3 and all((5*10**k)%3!=0 for k in range(12))'),
E('Une réduction trompeuse',r"Un élève écrit $(8+4)/4=8+1$. Expliquer son erreur et calculer correctement.",
r"La division porte sur toute la somme : $(8+4)/4=12/4=\res3$. On peut aussi diviser chaque terme : $8/4+4/4=2+1$. Simplifier seulement le terme 4 a laissé le 8 sans division.",
'Revenir au sens de la barre de fraction.','assert Rational(8+4,4)==3 and 8+1!=3'),
E('Deux étapes de lecture',r"Un lecteur lit $2/5$ d’un livre le lundi, puis $1/3$ de ce qui reste le mardi. Quelle fraction du livre reste-t-il ? Combien de pages pour un livre de 270 pages ?",
r"Après lundi, il reste $3/5$. Mardi, il lit $(1/3)\times(3/5)=1/5$ du livre entier. Il reste donc $3/5-1/5=\res{2/5}$. Cela représente $270\times2/5=\res{108\text{ pages}}$. Additionner $2/5$ et $1/3$ aurait confondu les références.",
'Identifier le tout auquel se rapporte chaque fraction.','assert (1-Rational(2,5))*(1-Rational(1,3))==Rational(2,5) and 270*Rational(2,5)==108'),
E('Des bouquets vendus',r"Une fleuriste vend les $2/3$ de ses bouquets le matin, puis les $3/4$ du reste l’après-midi. Le soir, il lui reste 9 bouquets. Combien en avait-elle au début ?",
r"Après le matin, il reste $1/3$ du stock. L’après-midi, elle vend les $3/4$ de ce tiers ; il en reste $1/4$, soit $(1/4)\times(1/3)=1/12$ du stock initial. Ces $1/12$ valent 9 bouquets : elle en avait $\res{108}$. Contrôle : 72 le matin, puis 27 l’après-midi, et $108-72-27=9$.",
'Exprimer ce qui reste comme une fraction du stock initial.','assert (1-Rational(2,3))*(1-Rational(3,4))==Rational(1,12) and 9*12==108 and 108-72-27==9'),
E('Une réserve d’eau',r"Une cuve est remplie aux $7/8$. On consomme $2/7$ de l’eau présente, puis on ajoute 30 L. La cuve est alors remplie aux $3/4$. Quelle est sa capacité ?",
r"Après consommation, la part remplie est $(7/8)(1-2/7)=5/8$. Les 30 L ajoutés représentent $3/4-5/8=1/8$ de la capacité. La capacité vaut donc $30\times8=\res{240\text{ L}}$. Contrôle : 210 L au départ, puis 150 L, puis 180 L, soit $3/4$ de 240 L.",
'Exprimer les volumes comme fractions d’une même capacité.','assert Rational(7,8)*Rational(5,7)==Rational(5,8) and 240*Rational(5,8)+30==240*Rational(3,4)'),
E('Des votes et des absents',r"Dans une classe, $5/6$ des élèves sont présents. Parmi eux, $3/5$ choisissent le projet A. Le projet A reçoit 15 voix. Combien y a-t-il d’élèves et d’absents ?",
r"La part de toute la classe qui vote A est $(5/6)(3/5)=1/2$. Les 15 voix représentent donc la moitié de la classe : $\res{30\text{ élèves}}$. Il y a $30/6=\res{5\text{ absents}}$ et 25 présents ; $3/5$ de 25 vaut bien 15.",
'Multiplier les proportions lorsque les ensembles sont emboîtés.','assert Rational(5,6)*Rational(3,5)==Rational(1,2) and 30-30*Rational(5,6)==5'),
E('Trouver toutes les possibilités',r"On cherche les entiers naturels $n$ tels que $n/12$ soit strictement supérieur à $2/3$ et strictement inférieur à $5/4$. Les donner tous.",
r"Les trois fractions se comparent avec le dénominateur 12 : $2/3=8/12$ et $5/4=15/12$. Il faut donc $8<n<15$. Les solutions sont $\res{9,10,11,12,13,14}$. Les deux bornes sont exclues à cause du mot « strictement ».",
'Transformer les comparaisons en un encadrement entier.','assert [n for n in range(25) if Rational(2,3)<Rational(n,12)<Rational(5,4)]==list(range(9,15))')
],reperes=['Priorités, signes et vocabulaire','Opérations et fractions irréductibles','Comparaisons et ensembles de nombres','Fractions dans les problèmes'])

chapitre(2,'puissances-racines','Puissances, racines et notation scientifique','1 · Nombres et calculs',
'Exposants · Préfixes · Ordres de grandeur · Équation $x^2=a$',
['Utiliser les puissances d’exposant entier.','Écrire et calculer en notation scientifique.','Résoudre une équation $x^2=a$ et un problème avec une racine carrée.'],['Produits, quotients et carrés des entiers de 0 à 12.'],[
r'''\essSection{1}{Puissances et notation scientifique}
\begin{definition}Pour $n$ entier positif, $a^n$ est le produit de $n$ facteurs égaux à $a$. Pour $a\ne0$, on pose $a^0=1$ et $a^{-n}=1/a^n$ : en divisant $10^3$ successivement par 10, on obtient $10^2$, $10^1$, $10^0=1$, puis $10^{-1}=0{,}1$.\end{definition}
\begin{propriete}Pour $a$ et $b$ non nuls et $m$, $n$ entiers relatifs :
\[a^m\times a^n=a^{m+n},\qquad \frac{a^m}{a^n}=a^{m-n},\qquad a^n\times b^n=(ab)^n.\]\end{propriete}
\begin{definition}La notation scientifique d’un nombre positif est $c\times10^p$, avec $1\le c<10$ et $p$ entier relatif. Par exemple $0{,}000056=5{,}6\times10^{-5}$.\end{definition}
\begin{savoirfaire}[Calculer en notation scientifique]Regrouper les coefficients, puis les puissances de 10. $(3\times10^5)(4\times10^{-2})=12\times10^3=1{,}2\times10^4$.\end{savoirfaire}
\begin{propriete}[Préfixes]nano : $10^{-9}$ ; micro (µ) : $10^{-6}$ ; milli : $10^{-3}$ ; kilo : $10^{3}$ ; méga : $10^{6}$ ; giga : $10^{9}$. Ainsi $1\text{ nm}=10^{-9}\text{ m}$ et $1\text{ Go}=10^9$ octets.\end{propriete}
\begin{attention}$a^m+a^n$ ne se transforme pas en $a^{m+n}$. Les règles sur les exposants concernent des produits et des quotients.\end{attention}''',
r'''\essSection{2}{Racine carrée et équation $x^2=a$}
\begin{definition}Pour $a\ge0$, $\sqrt a$ est l’unique nombre positif ou nul dont le carré vaut $a$. Ainsi $(\sqrt a)^2=a$. La racine carrée d’un nombre négatif n’est pas définie.\end{definition}
\begin{propriete}[Résoudre $x^2=a$]Si $a>0$, l’équation a deux solutions, $-\sqrt a$ et $\sqrt a$ : l’ensemble des solutions est $\{-\sqrt a\,;\sqrt a\}$. Si $a=0$, la seule solution est 0. Si $a<0$, il n’y a aucune solution : l’ensemble des solutions est vide, noté $\varnothing$.\end{propriete}
\begin{exemple}Pour $x^2=9$, on écrit $x^2-9=(x-3)(x+3)=0$ : les solutions sont $-3$ et 3. Graphiquement, la droite d’équation $y=9$ coupe la courbe de la fonction carré en deux points d’abscisses $-3$ et 3.\end{exemple}
\begin{savoirfaire}[Arrondir une mesure]Un carré d’aire 45 cm$^2$ a pour côté $\sqrt{45}$ cm, environ $6{,}71$ cm : une longueur est positive, on ne garde pas $-\sqrt{45}$. Conserver les valeurs exactes pendant les calculs et arrondir à la fin, à la précision demandée.\end{savoirfaire}
\begin{attention}$\sqrt{(-4)^2}=4$ : une racine carrée est toujours positive ou nulle. Et $\sqrt{a+b}$ n’est pas, en général, égal à $\sqrt a+\sqrt b$.\end{attention}'''],[
E('Comprendre un exposant',r"Écrire $7\times7\times7\times7$ comme une puissance. Calculer $2^{-3}$ et $9^0$.",r"Le premier produit vaut $\res{7^4}$. L’exposant négatif donne un inverse : $2^{-3}=1/2^3=\res{1/8}$. La base 9 est non nulle, donc $\res{9^0=1}$.","Relier l’écriture aux produits et aux inverses.","assert 7**4==2401 and Rational(2)**-3==Rational(1,8) and 9**0==1"),
E('Parenthèses et signe',r"Calculer $(-5)^2$, $-5^2$, $(-2)^3$ et $(-2)^4$.",r"Le carré de $-5$ vaut $\res{25}$, tandis que $-5^2=-(5^2)=\res{-25}$. Une puissance impaire de $-2$ est négative : $\res{-8}$ ; une puissance paire est positive : $\res{16}$.","Déterminer la base exacte avant de calculer.","assert (-5)**2==25 and -5**2==-25 and (-2)**3==-8 and (-2)**4==16"),
E('Règles de puissances',r"Écrire sous la forme d’une seule puissance : $3^4\times3^2$, $\dfrac{5^7}{5^3}$, $2^3\times5^3$ et $\dfrac{10^{-2}}{10^{4}}$.",r"Pour un produit de même base, on additionne les exposants : $\res{3^6}$. Pour le quotient, on les soustrait : $\res{5^4}$. Deux puissances de même exposant donnent $(2\times5)^3=\res{10^3}$. Enfin $10^{-2-4}=\res{10^{-6}}$.","Identifier la règle correspondant à chaque opération.","assert 3**4*3**2==3**6 and 5**7//5**3==5**4 and 2**3*5**3==10**3 and Rational(10)**-2/10**4==Rational(10)**-6"),
E('Écriture scientifique',r"Écrire $74000000$ et $0{,}000092$ en notation scientifique.",r"On déplace la virgule jusqu’à obtenir un coefficient entre 1 et 10 : $\res{7{,}4\times10^7}$ et $\res{9{,}2\times10^{-5}}$. Le signe négatif de l’exposant traduit ici un nombre inférieur à 1.","Contrôler le coefficient et le nombre de déplacements.","assert Rational('7.4')*10**7==74000000 and Rational('9.2')*Rational(10)**-5==Rational('0.000092')"),
E('Quelques racines',r"Calculer $\sqrt{144}$, $\sqrt{0{,}81}$ et $\sqrt{49/64}$.",r"On cherche des nombres positifs dont les carrés sont les données : $\res{12}$, $\res{0{,}9}$ et $\res{7/8}$. Par exemple $(7/8)^2=49/64$.","Utiliser les carrés connus en conservant le signe positif.","assert sqrt(144)==12 and sqrt(Rational(81,100))==Rational(9,10) and sqrt(Rational(49,64))==Rational(7,8)"),
E('Produit scientifique',r"Calculer $(6\times10^8)(4\times10^{-5})$ en notation scientifique.",r"Les coefficients donnent 24 et les puissances $10^{8-5}=10^3$. On obtient $24\times10^3=\res{2{,}4\times10^4}$. Le coefficient 24 n’était pas encore compris entre 1 et 10.","Regrouper puis normaliser le coefficient.","assert 6*10**8*4*Rational(10)**-5==24000"),
E('Quotient scientifique',r"Calculer $\dfrac{8{,}4\times10^{-3}}{2{,}1\times10^5}$.",r"Le quotient des coefficients vaut 4 et celui des puissances vaut $10^{-3-5}=10^{-8}$. Le résultat est $\res{4\times10^{-8}}$. On vérifie qu’il est petit, puisque l’on divise un petit nombre par un grand.","Soustraire l’exposant du dénominateur, même s’il est positif.","assert Rational('8.4')*Rational(10)**-3/(Rational('2.1')*10**5)==4*Rational(10)**-8"),
E('Des préfixes',r"Écrire en notation scientifique, dans l’unité indiquée : $4{,}7$ Go en octets ; 250 nm en mètres ; $0{,}6$ µs en secondes.",r"Giga vaut $10^9$ : $\res{4{,}7\times10^9}$ octets. Nano vaut $10^{-9}$ : $250\times10^{-9}=\res{2{,}5\times10^{-7}\text{ m}}$. Micro vaut $10^{-6}$ : $0{,}6\times10^{-6}=\res{6\times10^{-7}\text{ s}}$. Les coefficients sont ensuite ramenés entre 1 et 10.","Remplacer le préfixe par sa puissance de 10, puis normaliser.","assert 250*Rational(10)**-9==Rational('2.5')*Rational(10)**-7 and Rational('0.6')*Rational(10)**-6==6*Rational(10)**-7"),
E('Une équation $x^2=a$',r"Résoudre $x^2=49$, $x^2=7$, $x^2=0$ et $x^2=-4$. Donner chaque ensemble de solutions.",r"Les ensembles de solutions sont $\res{\{-7\,;7\}}$, $\res{\{-\sqrt7\,;\sqrt7\}}$, $\res{\{0\}}$ et $\res{\varnothing}$. Un carré n’est jamais négatif, ce qui explique le dernier cas.","Examiner d’abord le signe du second membre.","assert set(solve(x*x-49,x))=={-7,7} and set(solve(x*x-7,x))=={-sqrt(7),sqrt(7)} and solve(x*x,x)==[0] and solveset(x*x+4,x,domain=S.Reals)==S.EmptySet"),
E('Réfuter une règle',r"Réfuter $\sqrt{a+b}=\sqrt a+\sqrt b$ en choisissant deux nombres positifs simples.",r"Prendre $a=9$ et $b=16$ : $\sqrt{9+16}=\sqrt{25}=5$, tandis que $\sqrt9+\sqrt{16}=3+4=7$. Comme $5\ne7$, cet exemple suffit à réfuter l’affirmation générale.","Choisir un contre-exemple dont les deux calculs sont exacts.","assert sqrt(9+16)==5 and sqrt(9)+sqrt(16)==7"),
E('Une population qui double',r"Une culture contient 800 cellules. Leur nombre double toutes les 20 minutes, selon un modèle valable pendant l’expérience. Combien de cellules après 2 heures ? Écrire le résultat en notation scientifique.",r"Deux heures représentent 120 minutes, donc six doublements. Le nombre prévu est $800\times2^6=\res{51200}$, soit $\res{5{,}12\times10^4}$. On multiplie six fois par 2 ; on n’ajoute pas six fois 800.","Compter les périodes avant d’appliquer la puissance.","assert 120//20==6 and 800*2**6==51200"),
E('Une masse minuscule',r"Un lot de $4\times10^{12}$ particules a une masse totale de $1{,}8$ g. Dans ce modèle, toutes ont la même masse. Calculer la masse d’une particule en grammes, puis en kilogrammes.",r"On divise la masse totale par le nombre de particules : $1{,}8/(4\times10^{12})=0{,}45\times10^{-12}=\res{4{,}5\times10^{-13}\text{ g}}$. Comme $1\text{ g}=10^{-3}\text{ kg}$, cela vaut $\res{4{,}5\times10^{-16}\text{ kg}}$.","Diviser puis convertir sans perdre les puissances de 10.","assert Rational('1.8')/(4*10**12)==Rational('4.5')*Rational(10)**-13"),
E('Une distance astronomique',r"Un signal parcourt $3\times10^5$ km par seconde. Il voyage pendant 8 min 20 s. Quelle distance parcourt-il ? Donner aussi cette distance en mètres.",r"La durée vaut $8\times60+20=500$ s. La distance est $3\times10^5\times500=\res{1{,}5\times10^8\text{ km}}$. On multiplie par $10^3$ pour convertir en mètres : $\res{1{,}5\times10^{11}\text{ m}}$.","Utiliser des unités compatibles avant de multiplier.","assert (8*60+20)*3*10**5==150000000 and 150000000*1000==150000000000"),
E('Choisir le côté d’une dalle',r"Une dalle carrée a une aire de 2 m$^2$. Donner son côté exact en mètres, puis l’arrondir au millimètre. Peut-on le remplacer par 1,4 m pour calculer une aire exacte ?",r"Le côté $c$ vérifie $c^2=2$ avec $c>0$, donc $\res{c=\sqrt2\text{ m}}$, soit environ 1,414213 m. Au millimètre, on obtient $\res{1{,}414\text{ m}}$. Remplacer par 1,4 m donnerait $1{,}4^2=1{,}96$ m$^2$, différent de 2 : l’approximation ne conserve pas l’aire exacte.","Distinguer la longueur exacte et la mesure arrondie.","assert round(2**.5,3)==1.414 and Rational(14,10)**2!=2"),
E('Un cercle et trois droites',r"Dans un repère orthonormé, le cercle de centre $O$ et de rayon 5 contient les points $M(x\,;y)$ tels que $OM=5$, c’est-à-dire $x^2+y^2=25$ d’après Pythagore. On le coupe par les droites horizontales d’équations $y=3$, $y=5$ et $y=6$. Pour chacune, résoudre l’équation obtenue en $x$ et conclure.",r"Pour $y=3$ : $x^2=25-9=16$, donc deux points d’abscisses $\res{-4\text{ et }4}$. Pour $y=5$ : $x^2=0$, un seul point, $\res{(0\,;5)}$ : la droite touche le cercle. Pour $y=6$ : $x^2=-11$, $\res{\text{aucun point}}$. Le nombre d’intersections dépend de la distance de la droite au centre, comparée au rayon.","Se ramener à une équation $x^2=a$ et discuter selon le signe de $a$.","assert set(solve(x*x+9-25,x))=={-4,4} and solve(x*x+25-25,x)==[0] and solveset(x*x+36-25,x,domain=S.Reals)==S.EmptySet",figure='cercle-droites')
],reperes=['Puissances d’exposant entier','Notation scientifique et préfixes','Racine carrée et équation $x^2=a$','Problèmes de grandeurs et de racines'])

chapitre(3,'arithmetique','Multiples, diviseurs et nombres premiers','1 · Nombres et calculs',
'Divisibilité · Décomposition · Fractions irréductibles · Périodicités',
['Décomposer un entier en facteurs premiers.','Simplifier une fraction et résoudre des partages.','Organiser une recherche de multiples communs.'],['Division euclidienne et critères de divisibilité par 2, 3, 5 et 9.'],[
r'''\essSection{1}{Divisibilité et nombres premiers}
\begin{definition}Un entier $a$ est un multiple d’un entier non nul $b$ lorsque $a=bk$ pour un entier $k$. Alors $b$ est un diviseur de $a$. Un nombre premier est un entier supérieur ou égal à 2 ayant exactement deux diviseurs positifs : 1 et lui-même.\end{definition}
\begin{exemple}2, 3, 5, 7, 11 et 13 sont premiers. Le nombre 1 ne l’est pas. Le nombre 91 ne l’est pas non plus : $91=7\times13$.\end{exemple}
\begin{propriete}Un entier est divisible par 2 si son dernier chiffre est pair, par 5 s’il se termine par 0 ou 5, par 3 ou par 9 si la somme de ses chiffres l’est. Un nombre peut vérifier plusieurs critères.\end{propriete}
\begin{savoirfaire}[Décomposer]Diviser successivement par des nombres premiers. Par exemple $60=2^2\times3\times5$ et $360=2^3\times3^2\times5$. Continuer jusqu’à ce que tous les facteurs soient premiers.\end{savoirfaire}
\begin{attention}Pour prouver qu’un nombre est composé, un seul diviseur autre que 1 et lui-même suffit. Pour prouver qu’il est premier, il faut exclure tous les diviseurs nécessaires, pas seulement 2 et 3.\end{attention}''',
r'''\essSection{2}{Simplifier et organiser des groupes}
\begin{definition}Une fraction d’entiers est irréductible lorsque numérateur et dénominateur n’ont aucun diviseur commun positif autre que 1.\end{definition}
\begin{exemple}$84/150=(2^2\times3\times7)/(2\times3\times5^2)=14/25$. Les facteurs communs ont été simplifiés ; 14 et 25 n’en ont plus.\end{exemple}
\begin{savoirfaire}[Le plus grand nombre de groupes identiques]Le nombre de groupes doit diviser chacun des stocks. Chercher leur plus grand diviseur commun, à l’aide des décompositions ou de la liste des diviseurs.\end{savoirfaire}
\begin{savoirfaire}[La première rencontre de phénomènes périodiques]Le temps écoulé doit être un multiple de chaque période. Chercher le plus petit multiple commun strictement positif. Calendriers, engrenages et cycles d’éclosion d’espèces animales relèvent de ce raisonnement.\end{savoirfaire}
\begin{attention}Le mot « plus grand » ou « premier » demande une justification de l’optimalité. Donner un partage possible ou une rencontre possible ne suffit pas.\end{attention}
\otIntertitre{Avec un tableur}
Une colonne d’entiers et une colonne de restes permettent de tester les diviseurs. Contrôler la liste obtenue avec une décomposition en facteurs premiers.'''],[
E('Tester des diviseurs',r"Parmi 2, 3, 5, 9 et 10, lesquels divisent 2340 ?",r"2340 est pair et se termine par 0 : 2, 5 et 10 conviennent. La somme de ses chiffres vaut 9 : 3 et 9 conviennent aussi. Les cinq nombres proposés sont donc des diviseurs.","Utiliser les critères puis contrôler les quotients.","assert all(2340%d==0 for d in [2,3,5,9,10])"),
E('Premier ou composé ?',r"Parmi 1, 2, 17, 21 et 49, relever les nombres premiers et justifier les exclusions.",r"$\res{2\text{ et }17}$ sont premiers. Le nombre 1 n’a qu’un diviseur positif ; $21=3\times7$ et $49=7^2$ sont composés. Pour 17, les seuls diviseurs premiers à tester sont 2 et 3, car $5^2=25>17$ ; ils ne divisent pas 17.","Appliquer la définition et fournir des facteurs quand c’est possible.","assert [n for n in [1,2,17,21,49] if isprime(n)]==[2,17]"),
E('Décomposer un entier',r"Décomposer 420 en facteurs premiers.",r"$420=42\times10=(2\times3\times7)(2\times5)=\res{2^2\times3\times5\times7}$. Tous les facteurs sont premiers ; leur produit redonne 420.","Poursuivre la décomposition jusqu’aux facteurs premiers.","assert factorint(420)=={2:2,3:1,5:1,7:1}"),
E('Une fraction irréductible',r"Rendre $198/252$ irréductible.",r"Les décompositions sont $198=2\times3^2\times11$ et $252=2^2\times3^2\times7$. En simplifiant $2\times3^2$, on obtient $\res{11/14}$. Les diviseurs de 11 ne divisent pas 14.","Simplifier tous les facteurs premiers communs.","assert Rational(198,252)==Rational(11,14)"),
E('Écrire des multiples',r"Lister les multiples de 14 compris entre 70 et 130, bornes comprises.",r"On part de $14\times5=70$ puis on ajoute 14 : $\res{70,84,98,112,126}$. Le suivant vaut 140 et dépasse la borne supérieure.","Encadrer les multiplicateurs entiers.","assert [n for n in range(70,131) if n%14==0]==[70,84,98,112,126]"),
E('Tous les diviseurs',r"Donner tous les diviseurs positifs de 72 et expliquer pourquoi la liste est complète.",r"On utilise les paires $1\times72$, $2\times36$, $3\times24$, $4\times18$, $6\times12$ et $8\times9$. On obtient $\res{1,2,3,4,6,8,9,12,18,24,36,72}$. Au-delà de 8, chaque diviseur a déjà son partenaire dans une paire, car $9\times9>72$.","Chercher des paires de facteurs sans doublons.","assert divisors(72)==[1,2,3,4,6,8,9,12,18,24,36,72]"),
E('Un chiffre inconnu',r"Déterminer les chiffres $a$ pour lesquels le nombre $45a$ est divisible par 3 et par 2.",r"La divisibilité par 2 impose $a\in\{0,2,4,6,8\}$. La somme des chiffres vaut $9+a$ ; elle est divisible par 3 pour $a=0,3,6,9$. Les chiffres communs aux deux listes donnent $\res{a=0\text{ ou }6}$.","Combiner les critères, puis vérifier les candidats.","assert [a for a in range(10) if (450+a)%6==0]==[0,6]"),
E('Une grande fraction',r"Réduire $\dfrac{2^4\times3^2\times7}{2^2\times3^3\times5}$.",r"On simplifie $2^2$ et $3^2$. Il reste $(2^2\times7)/(3\times5)=\res{28/15}$. Aucun facteur 2 ou 7 ne peut encore se simplifier avec 3 ou 5.","Soustraire les exposants seulement pour les facteurs de même base.","assert Rational(2**4*3**2*7,2**2*3**3*5)==Rational(28,15)"),
E('Un carré parfait ?',r"Le nombre $2^4\times3^3$ est-il un carré d’entier ? Par quel plus petit entier positif le multiplier pour obtenir un carré ?",r"Un carré a des exposants pairs dans sa décomposition. L’exposant 3 du facteur 3 est impair : le nombre n’est pas un carré. Multiplier par $\res3$ donne $2^4\times3^4=(2^2\times3^2)^2=\res{36^2}$. Un facteur 3 est nécessaire.","Observer la parité de chaque exposant premier.","assert 2**4*3**3*3==36**2 and not sqrt(2**4*3**3).is_integer"),
E('Un calcul par tableur',r"Une colonne A contient les entiers de 1 à 20. La cellule B2 contient la formule \code{=MOD(84;A2)}. Que signifie un résultat nul ? Quels diviseurs de 84 inférieurs ou égaux à 20 obtient-on ?",r"La fonction MOD calcule le reste de la division par la valeur de A2. Un reste nul signifie que cet entier divise 84. La liste cherchée est $\res{1,2,3,4,6,7,12,14}$. On ne trouve pas les diviseurs supérieurs à 20 avec cette seule colonne.","Relier le reste nul à la définition d’un diviseur.","assert [d for d in range(1,21) if 84%d==0]==[1,2,3,4,6,7,12,14]"),
E('Préparer des lots',r"On possède 156 cartes rouges et 204 cartes bleues. Former le plus grand nombre de lots identiques sans reste, avec les deux couleurs dans chaque lot. Donner le nombre de lots et leur contenu.",r"Le nombre de lots doit diviser 156 et 204. Or $156=2^2\times3\times13$ et $204=2^2\times3\times17$ : le plus grand diviseur commun vaut 12. On peut former $\res{12\text{ lots}}$, contenant chacun $\res{13\text{ rouges et }17\text{ bleues}}$. Aucun diviseur commun n’est plus grand.","Traduire le partage en diviseurs communs.","assert gcd(156,204)==12 and 156//12==13 and 204//12==17"),
E('Des cigales périodiques',r"Dans un modèle simplifié, une espèce de cigales sort de terre tous les 13 ans et une autre tous les 17 ans. Les deux sont sorties la même année en 2024. En quelle année cette coïncidence se reproduira-t-elle pour la première fois ?",r"Le nombre d’années écoulées doit être un multiple commun de 13 et de 17. Ces deux nombres sont premiers et distincts : le plus petit multiple commun positif est $13\times17=221$. La prochaine coïncidence aura lieu en $\res{2245}$. Des périodes premières entre elles rendent les rencontres rares.","Chercher le premier multiple commun aux deux périodes.","assert ilcm(13,17)==221 and 2024+221==2245"),
E('Daller un rectangle',r"Un rectangle de 180 cm sur 252 cm doit être recouvert de carrés identiques, sans découpe. Les côtés des carrés sont des nombres entiers de centimètres. Trouver le plus grand côté possible et le nombre de carrés.",r"Le côté doit diviser 180 et 252. Leur plus grand diviseur commun vaut 36. On place $252/36=7$ carrés sur la longueur et $180/36=5$ sur la largeur : $\res{35\text{ carrés de côté }36\text{ cm}}$. Le contrôle par les aires donne $35\times36^2=180\times252$.","Utiliser un diviseur commun pour les deux dimensions.","assert gcd(180,252)==36 and 5*7*36**2==180*252",figure='dallage'),
E('Un stock à retrouver',r"Un stock compte entre 500 et 600 objets. Il se range sans reste par paquets de 8, de 9 ou de 15. Déterminer toutes les possibilités.",r"Un tel nombre doit être multiple de $2^3$, de $3^2$ et de 5, donc de $8\times9\times5=360$. Les multiples voisins sont 360 et 720. Aucun n’est entre 500 et 600 : $\res{\text{aucune solution}}$. Un énoncé peut conduire légitimement à l’impossibilité.","Tester la compatibilité des contraintes avant de chercher un nombre.","assert ilcm(8,9,15)==360 and not [n for n in range(500,601) if n%8==n%9==n%15==0]"),
E('Des engrenages',r"Deux roues de 24 et 40 dents engrènent. Deux dents marquées sont en contact au départ. Après combien de passages de dents retrouve-t-on ce contact ? Combien de tours fait chaque roue ?",r"Le nombre de dents passées au contact doit être multiple de 24 et de 40. Le premier multiple commun est 120. La petite roue fait $120/24=\res5$ tours et la grande $120/40=\res3$ tours, en sens opposés. Le contact initial revient après $\res{120\text{ passages}}$.","Compter les dents au contact plutôt que confondre les nombres de tours.","assert ilcm(24,40)==120 and 120//24==5 and 120//40==3",figure='engrenages')
],reperes=['Divisibilité et nombres premiers','Décomposition et fractions irréductibles','Diviseurs communs et partages','Multiples communs et périodicité'])
